data.original:
/* Dashboard data widgets, biometric/genome/correlation cards, and theme tweaks. */

.db-hero-bio {
  display: grid; grid-template-columns: 1fr auto; align-items: center;
  gap: 24px; cursor: pointer;
  width: 100%;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
  padding: 0;
}
.db-hero-bio-left { display: flex; align-items: baseline; gap: 16px; min-width: 0; }
.db-hero-bio-num {
  font-family: var(--font-display); font-size: 86px; font-weight: 700;
  letter-spacing: 0; line-height: 1;
  background: var(--accent-gradient);
  -webkit-background-clip: text; background-clip: text; color: transparent;
}
.db-hero-bio-label { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
.db-hero-bio-label .top {
  font-family: var(--font-mono); font-size: 11px; font-weight: 700;
  text-transform: uppercase; color: var(--text-muted);
}
.db-hero-bio-label .actual { font-size: 13px; color: var(--text-secondary); }
.db-hero-bio-label .delta { font-family: var(--font-mono); font-size: 13px; color: var(--red); }
.db-hero-bio-right {
  width: 220px; display: flex; flex-direction: column; gap: 10px;
  font-family: var(--font-mono); font-size: 11px; color: var(--text-secondary);
}
.db-hero-row,
.db-hero-scale { display: flex; justify-content: space-between; gap: 10px; }
.db-hero-row strong { color: var(--text-primary); }
.db-hero-bio-bar {
  width: 100%; height: 8px; border-radius: 999px; overflow: hidden;
  background: var(--bg-hover); border: 1px solid var(--border);
}
.db-hero-bio-bar > div { height: 100%; background: var(--accent-gradient); }
.db-spark { width: 100%; height: 100%; color: var(--accent); overflow: visible; }
.db-spark polyline {
  fill: none; stroke: currentColor; stroke-width: 2;
  stroke-linecap: round; stroke-linejoin: round;
}
.db-spark circle { fill: currentColor; }
.db-spark-high,
.db-spark-low { color: var(--red); }
.db-spark-normal { color: var(--green); }
.db-spark-empty { display: block; height: 2px; background: var(--border); border-radius: 2px; }
.db-quick-marker-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}
.db-stat-widget {
  width: 100%; min-height: 150px; padding: 0; border: 0; background: transparent;
  color: var(--text-primary); display: flex; flex-direction: column; gap: 8px;
  align-items: stretch; text-align: left; font: inherit; cursor: pointer;
}
.db-quick-marker-grid .db-stat-widget {
  min-height: 168px;
  padding: 14px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  transition: background 0.15s, border-color 0.15s, transform 0.05s;
}
.db-quick-marker-grid .db-stat-widget:hover {
  background: var(--bg-hover);
  border-color: color-mix(in srgb, var(--accent) 45%, var(--border));
}
.db-stat-widget:active { transform: translateY(1px); }
.db-stat-widget:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  border-radius: var(--radius-sm);
}
.db-stat-head { display: flex; align-items: center; gap: 7px; min-width: 0; }
.db-stat-head span:last-child {
  min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  font-family: var(--font-mono); font-size: 11px; font-weight: 700; text-transform: uppercase;
  color: var(--text-secondary);
}
.db-status-dot {
  width: 11px; height: 11px; border-radius: 50%; display: inline-block;
  background: var(--text-muted); flex-shrink: 0;
}
.db-status-dot.db-status-normal { background: var(--green); }
.db-status-dot.db-status-high { background: var(--red); }
.db-status-dot.db-status-low { background: var(--yellow); }
.db-stat-widget.db-status-high .db-stat-delta,
.db-stat-widget.db-status-low .db-stat-delta { color: var(--red); }
.db-stat-value {
  font-family: var(--font-display); font-size: 30px; line-height: 1; font-weight: 700;
  font-variant-numeric: tabular-nums;
}
.db-stat-value small { margin-left: 5px; font-size: 12px; color: var(--text-muted); font-weight: 500; }
.db-stat-delta { font-family: var(--font-mono); font-size: 11px; color: var(--text-muted); }
.db-stat-widget .db-spark { height: 34px; margin-top: auto; }
.db-stat-reason {
  min-height: 18px;
  padding-top: 2px;
  border-top: 1px solid var(--border);
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Focus Card */
.focus-card {
  display: flex; align-items: center; gap: 12px;
  background: var(--bg-card); border: 1px solid var(--border); border-radius: var(--radius);
  padding: 14px 18px; margin-top: 16px;
  border-left: 3px solid var(--accent);
  position: relative; overflow: hidden;
}
.focus-card::before {
  content: ''; position: absolute; left: 0; top: 0; bottom: 0; width: 3px;
  background: var(--accent-gradient);
}
.focus-card-icon { font-size: 20px; flex-shrink: 0; }
.focus-card-body { flex: 1; min-width: 0; font-size: 14px; line-height: 1.5; color: var(--text-primary); }
.focus-card-text { display: block; }
.focus-card-refresh {
  flex-shrink: 0; background: none; border: 1px solid var(--border); border-radius: 6px;
  color: var(--text-muted); font-size: 16px; width: 30px; height: 30px; cursor: pointer;
  display: flex; align-items: center; justify-content: center; transition: color 0.15s, border-color 0.15s;
}
.focus-card-refresh:hover { color: var(--accent); border-color: var(--accent); }
.focus-card-shimmer {
  display: block; height: 18px; width: 80%; border-radius: 4px;
  background: linear-gradient(90deg, var(--bg-hover) 25%, var(--border) 50%, var(--bg-hover) 75%);
  background-size: 200% 100%;
  animation: shimmer 1.5s ease-in-out infinite;
}

/* Interpretive Lens Section */
.lens-section {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 12px 16px;
  margin-top: 10px;
  cursor: pointer;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  border-left: 3px solid var(--purple);
  font-size: 13px;
  color: var(--text-secondary);
  line-height: 1.5;
  transition: border-color 0.15s, background 0.15s;
}
.lens-section:hover {
  border-color: var(--purple);
  background: var(--bg-hover);
}
.lens-section-icon {
  font-size: 16px;
  flex-shrink: 0;
  margin-top: 1px;
}
.lens-section-body {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.lens-section-label {
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--purple);
}
.lens-section-text {
  white-space: pre-wrap;
  word-break: break-word;
}
.lens-section-edit {
  font-size: 14px;
  flex-shrink: 0;
  color: var(--text-muted);
  opacity: 0;
  transition: opacity 0.15s;
  margin-top: 1px;
}
.lens-section:hover .lens-section-edit {
  opacity: 1;
}
.lens-section-empty { border-style: dashed; border-left-style: dashed; border-color: var(--border); opacity: 0.7; }
.lens-section-empty:hover { border-color: var(--purple); opacity: 1; }
.lens-section-empty .lens-section-text { font-style: italic; color: var(--text-muted); }

/* Trend Alert Cards */
.trend-alert-card {
  display: flex; align-items: center; gap: 12px; padding: 10px 14px;
  background: var(--bg-card); border-radius: var(--radius-sm);
  border: 1px solid var(--border); cursor: pointer; transition: background 0.15s;
  margin-bottom: 6px;
}
.trend-alert-card:hover { background: var(--bg-hover); }
.alerts-section { margin-bottom: 32px; }
.alerts-title {
  font-family: var(--font-display); font-size: 16px; font-weight: 600; margin-bottom: 12px;
  display: flex; align-items: center; gap: 8px;
}
.alert-card {
  background: var(--bg-card); border-radius: var(--radius-sm);
  border: 1px solid var(--border); padding: 14px 18px; margin-bottom: 8px;
  display: flex; align-items: center; gap: 12px; cursor: pointer; transition: all 0.15s;
}
.alert-card:hover { border-color: var(--accent); }
.alert-card.alert-high { border-left: 3px solid var(--red); }
.alert-card.alert-low { border-left: 3px solid var(--yellow); }
.alert-indicator {
  font-family: var(--font-mono); font-size: 11px; font-weight: 700; padding: 2px 8px; border-radius: 4px; white-space: nowrap; flex-shrink: 0;
}
.alert-high .alert-indicator { background: var(--red-bg); color: var(--red); }
.alert-low .alert-indicator { background: var(--yellow-bg); color: var(--yellow); }
.alert-name { font-size: 14px; font-weight: 500; flex: 1; }
.alert-value { font-family: var(--font-mono); font-size: 14px; font-weight: 600; font-variant-numeric: tabular-nums; }
.alert-ref { font-size: 12px; color: var(--text-muted); width: 120px; text-align: right; }
.trend-alert-danger { border-left: 3px solid var(--red); }
.trend-alert-warning { border-left: 3px solid var(--yellow); }
.trend-alert-sudden { border-left: 3px solid var(--orange); }
.trend-alert-arrow { font-size: 20px; flex-shrink: 0; line-height: 1; width: 24px; text-align: center; overflow: hidden; }
.trend-alert-danger .trend-alert-arrow { color: var(--red); }
.trend-alert-warning .trend-alert-arrow { color: var(--yellow); }
.trend-alert-sudden .trend-alert-arrow { color: var(--orange); }
.trend-alert-info { flex: 1; min-width: 0; }
.trend-alert-name { font-size: 13px; font-weight: 600; }
.trend-alert-cat { font-size: 11px; color: var(--text-muted); font-weight: 400; margin-left: 6px; }
.trend-alert-label { font-size: 12px; color: var(--text-secondary); margin-top: 2px; }
.trend-alert-spark {
  font-family: var(--font-mono); font-size: 12px; color: var(--text-secondary); white-space: nowrap;
  font-variant-numeric: tabular-nums; flex-shrink: 0;
}

@media (max-width: 640px) {
  .dashboard-widgets,
  .lens-page-widgets {
    gap: 12px;
  }
  .dashboard-widget {
    min-width: 0;
    padding: 14px;
  }
  .dashboard-widget-chrome {
    align-items: flex-start;
    flex-wrap: wrap;
  }
  .dashboard-widget-description {
    white-space: normal;
  }
  .dashboard-widget-tools {
    width: 100%;
    justify-content: flex-start;
    flex-wrap: wrap;
  }
  .dashboard-widget-tool,
  .lens-widget-dashboard-toggle {
    height: auto;
    min-height: 30px;
    line-height: 1.25;
    white-space: normal;
  }
  .db-quick-marker-grid {
  grid-template-columns: 1fr;
  gap: 10px;
}
  .db-quick-marker-grid .db-stat-widget {
  min-height: 128px;
  padding: 12px;
}
  .db-stat-value {
    font-size: clamp(24px, 10vw, 30px);
    overflow-wrap: anywhere;
  }
  .db-stat-value small {
    display: block;
    margin: 4px 0 0;
  }
}
@media (max-width: 600px) {
  .trend-alert-spark { display: none; }
}
.db-spotlight {
  display: flex;
  flex-direction: column;
  gap: 14px;
  cursor: pointer;
  width: 100%;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
  padding: 0;
}
.db-spotlight:focus-visible,
.db-hero-bio:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  border-radius: var(--radius-sm);
}
.db-spotlight-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}
.db-spotlight-name {
  font-family: var(--font-display);
  font-size: 22px;
  font-weight: 700;
}
.db-spotlight-meta {
  margin-top: 4px;
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: 11px;
}
.db-spotlight-priority {
  display: inline-flex;
  align-items: center;
  min-height: 22px;
  margin-top: 7px;
  padding: 2px 7px;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: var(--bg-hover);
  color: var(--text-secondary);
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
}
.db-spotlight-value {
  font-family: var(--font-mono);
  font-size: 22px;
  font-weight: 800;
  text-align: right;
  white-space: nowrap;
}
.db-spotlight-value small {
  display: block;
  margin-top: 2px;
  color: var(--text-muted);
  font-size: 10px;
  font-weight: 500;
}
.db-spotlight .db-spark {
  height: 150px;
}
.labs-priority-banner {
  width: 100%;
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr) minmax(90px, 150px) auto;
  align-items: center;
  gap: 12px;
  margin: 0 0 16px;
  padding: 12px 14px;
  border: 1px solid var(--border);
  border-left: 5px solid var(--accent);
  border-radius: var(--radius-sm);
  background: color-mix(in srgb, var(--bg-secondary) 72%, transparent);
  color: var(--text-primary);
  text-align: left;
  font: inherit;
  cursor: pointer;
}
.labs-priority-banner:hover {
  border-color: var(--accent);
  background: var(--bg-hover);
}
.labs-priority-banner:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}
.labs-priority-copy {
  min-width: 0;
  display: grid;
  gap: 2px;
}
.labs-priority-kicker {
  color: var(--accent);
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
}
.labs-priority-copy strong {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 14px;
}
.labs-priority-copy small {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
}
.labs-priority-spark {
  height: 28px;
  min-width: 0;
}
.labs-priority-value {
  font-family: var(--font-mono);
  font-size: 16px;
  font-weight: 800;
  text-align: right;
  white-space: nowrap;
}
.labs-priority-value small {
  display: block;
  margin-top: 2px;
  color: var(--text-muted);
  font-size: 10px;
  font-weight: 500;
}
.db-key-trend-list { display: grid; gap: 6px; min-width: 0; }
.db-key-trend-row {
  width: 100%;
  min-height: 58px;
  display: grid;
  grid-template-columns: 18px minmax(0, 1.3fr) minmax(100px, 0.8fr) 92px minmax(110px, 0.7fr);
  align-items: center;
  gap: 12px;
  padding: 10px;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-primary);
  text-align: left;
  font: inherit;
  cursor: pointer;
  transition: background 0.12s, border-color 0.12s;
}
.db-key-trend-row:hover { background: var(--bg-hover); border-color: var(--border); }
.db-key-trend-row:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}
.db-key-trend-name-wrap { min-width: 0; }
.db-key-trend-name {
  display: block;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 13px;
  font-weight: 800;
}
.db-key-trend-cat {
  display: block;
  margin-top: 3px;
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: 10px;
  text-transform: uppercase;
}
.db-key-trend-spark { height: 28px; min-width: 0; }
.db-key-trend-latest,
.db-key-trend-signal {
  min-width: 0;
  text-align: right;
  font-family: var(--font-mono);
}
.db-key-trend-latest strong,
.db-key-trend-signal strong {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 13px;
}
.db-key-trend-latest small,
.db-key-trend-signal small {
  display: block;
  margin-top: 3px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--text-muted);
  font-size: 10px;
}
.db-insights-list {
  display: grid;
  gap: 10px;
}
.db-insight {
  width: 100%;
  padding: 14px 16px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
  background: var(--bg-hover);
  color: var(--text-primary);
  display: flex;
  flex-direction: column;
  gap: 6px;
  align-items: flex-start;
  text-align: left;
  font: inherit;
  cursor: pointer;
}
.db-insight-danger {
  border-left: 3px solid var(--red);
}
.db-insight-warn {
  border-left: 3px solid var(--yellow);
}
.db-insight-good {
  border-left: 3px solid var(--green);
}
.db-insight-info {
  border-left: 3px solid var(--accent);
}
.db-insight-tag {
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--text-muted);
}
.db-insight strong {
  font-size: 14px;
}
.db-insight span:last-child {
  color: var(--text-secondary);
  font-size: 13px;
  line-height: 1.45;
}
.db-wearable-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 10px; }
.db-biometric-overview-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 12px;
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: 11px;
}
.db-biometric-overview-actions {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  flex-wrap: wrap;
}
.db-biometric-sync-status {
  color: var(--text-muted);
}
.db-biometric-sync-status.is-stale {
  color: var(--yellow);
}
.db-biometric-sync-btn {
  min-height: 30px;
  padding: 0 10px;
}
.db-biometric-tile-wrap {
  position: relative;
  min-width: 0;
}
.db-biometric-tile-wrap > .db-wearable-tile,
.db-biometric-tile-wrap > .wearable-card {
  width: 100%;
  min-height: 104px;
}
.wearable-card.db-biometric-manual-empty {
  background: var(--bg-hover);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 10px 12px 8px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
  margin: 0;
  opacity: 1;
  box-shadow: none;
  color: var(--text-primary);
  cursor: pointer;
  transition: border-color 0.15s ease, transform 0.15s ease;
}
.wearable-card.db-biometric-manual-empty:hover {
  border-color: var(--accent);
  opacity: 1;
  transform: translateY(-1px);
}
.wearable-card.db-biometric-manual-empty:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}
.db-biometric-manual-empty .wearable-card-top,
.db-biometric-manual-empty .wearable-card-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
.db-biometric-manual-empty .wearable-card-bottom {
  min-height: 18px;
}
.db-biometric-manual-empty .wearable-metric-name {
  min-width: 0;
  overflow: hidden;
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}
.db-biometric-manual-empty .wearable-value-row {
  display: flex;
  align-items: baseline;
  justify-content: flex-start;
  gap: 4px;
  min-height: 24px;
}
.db-biometric-manual-empty .wearable-value {
  color: var(--text-muted);
  font-size: 22px;
  font-variant-numeric: tabular-nums;
  font-weight: 400;
  line-height: 1;
}
.db-biometric-manual-empty .wearable-empty-cta {
  color: var(--accent);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.02em;
}
.db-biometric-remove {
  position: absolute;
  top: 8px;
  right: 8px;
  width: 30px;
  height: 30px;
  border: 1px solid var(--border);
  border-radius: 999px;
  background: color-mix(in srgb, var(--bg-secondary) 92%, transparent);
  color: var(--text-muted);
  font: inherit;
  line-height: 1;
  cursor: pointer;
  opacity: 0;
  transition: opacity 0.15s, color 0.15s, border-color 0.15s;
}
.db-biometric-tile-wrap:hover .db-biometric-remove,
.db-biometric-remove:focus-visible {
  opacity: 1;
}
.db-biometric-remove:hover {
  color: var(--status-high);
  border-color: var(--status-high);
}
.db-wearable-tile {
  min-height: 104px; padding: 14px; border-radius: var(--radius-sm);
  border: 1px solid var(--border); background: var(--bg-hover);
  color: var(--text-primary); display: flex; flex-direction: column;
  align-items: stretch; justify-content: space-between; text-align: left;
