}
.dashboard-widget:hover { border-color: color-mix(in srgb, var(--accent) 35%, var(--border)); }
.dashboard-widget-half { grid-column: span 6; }
.dashboard-widget-quarter { grid-column: span 3; }
.dashboard-widget-third { grid-column: span 4; }
.dashboard-widget-two-third { grid-column: span 8; }
.dashboard-widget-chrome {
  display: flex; align-items: center; gap: 10px;
  margin-bottom: 14px; min-width: 0;
}
.dashboard-widget-handle {
  display: none; color: var(--text-muted); font-family: var(--font-mono);
  font-size: 13px; line-height: 1; cursor: grab;
}
.dashboard-widget-heading { flex: 1; min-width: 0; }
.dashboard-widget-source {
  font-family: var(--font-mono); font-size: 10px; font-weight: 800;
  color: var(--accent); text-transform: uppercase; margin-bottom: 2px;
}
.dashboard-widget-title {
  font-family: var(--font-display); font-size: 14px; font-weight: 700;
  text-transform: uppercase; color: var(--text-primary); letter-spacing: 0;
}
.dashboard-widget-description {
  margin-top: 2px; font-family: var(--font-mono); font-size: 11px; color: var(--text-muted);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.dashboard-widget-tools { display: flex; align-items: center; gap: 6px; flex-shrink: 0; }
.dashboard-widget-tool {
  min-width: 30px; height: 30px; padding: 0 9px; border-radius: var(--radius-sm);
  border: 1px solid var(--border); background: var(--bg-secondary);
  color: var(--text-primary); font: inherit; font-size: 12px; cursor: pointer;
}
.dashboard-widget-tool:hover:not(:disabled) { border-color: var(--accent); background: var(--bg-hover); }
.dashboard-widget-tool:disabled { opacity: 0.45; cursor: default; }
.dashboard-widget-body { min-width: 0; }
.dashboard-widget-body > .lens-section:first-child,
.dashboard-widget-body > .focus-card:first-child,
.dashboard-widget-body > .light-today-strip:first-child,
.dashboard-widget-body > .wearable-strip:first-child,
.dashboard-widget-body > .wearable-strip-empty:first-child,
.dashboard-widget-body > .genetics-section:first-child {
  margin-top: 0;
}
.dashboard-widget-body > .alerts-section,
.dashboard-widget-body > .notes-section { margin-bottom: 0; }
.dashboard-widget-body > .focus-card,
.dashboard-widget-body > .light-today-strip,
.dashboard-widget-body > .wearable-strip,
.dashboard-widget-body > .wearable-strip-empty,
.dashboard-widget-body > .genetics-section,
.dashboard-widget-body > .lens-section {
  box-shadow: none;
}
.dashboard-widget[data-widget-id="focus"] .focus-card {
  align-items: flex-start;
  margin: 0;
}
.dashboard-widget-inline-controls {
  display: flex; align-items: center; gap: 12px; flex-wrap: wrap; margin-bottom: 12px;
}
.biology-score-header-actions {
  display: flex;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
}
.biology-score-header-actions .dashboard-action-btn {
  margin-right: 2px;
}
.dashboard-widget-empty {
  padding: 12px 0; color: var(--text-muted); font-size: 13px; font-style: italic;
}
.dashboard-widgets.is-organizing .dashboard-widget {
  padding: 12px; border: 1px dashed var(--border); border-radius: var(--radius);
  background: color-mix(in srgb, var(--bg-card) 46%, transparent);
}
.dashboard-widgets.is-organizing { grid-auto-flow: row; }
.dashboard-widgets.is-organizing .dashboard-widget:hover {
  border-color: var(--accent); background: color-mix(in srgb, var(--accent) 5%, var(--bg-card));
}
.dashboard-widgets.is-organizing .dashboard-widget-handle { display: block; }
.dashboard-organize-footer { margin-top: 18px; justify-content: flex-end; }
.lens-widget-dashboard-toggle { width: auto; white-space: nowrap; }

/* AI personalization CTA - inline pill that adapts to which feature is missing. */
.dashboard-cta { @apply gb:dashboard-ai-pill; }
.dashboard-cta:hover { @apply gb:dashboard-ai-pill-hover; }
.dashboard-cta:active { @apply gb:dashboard-ai-pill-active; }
.dashboard-cta:focus-visible { @apply gb:dashboard-ai-pill-focus; }
.dashboard-cta-icon { @apply gb:dashboard-ai-pill-icon; }
.dashboard-cta-plus { @apply gb:dashboard-ai-pill-plus; }

@media (max-width: 1100px) {
  .dashboard-widget-half,
  .dashboard-widget-two-third { grid-column: span 12; }
  .dashboard-widget-quarter,
  .dashboard-widget-third { grid-column: span 6; }
