core.original:
/* Dashboard greeting, sticky actions, and shared dashboard action buttons. */

.dashboard-greeting {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 16px;
}
.category-header { margin-bottom: 24px; }
.dashboard-greeting h1 {
  margin: 0;
  font-family: var(--font-display);
  font-size: 32px;
  line-height: 1.08;
  font-weight: 700;
  letter-spacing: 0;
  color: var(--text-primary);
}
.dashboard-greeting-kicker {
  margin-bottom: 5px;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--text-muted);
}
.dashboard-greeting-sub {
  margin-top: 6px;
  font-family: var(--font-mono);
  font-size: 12px;
  color: var(--text-secondary);
}
.dashboard-widget-picker-actions, .dashboard-organize-footer {
  display: flex; align-items: center; gap: 8px; flex-wrap: wrap;
}
.dashboard-sticky-actions {
  position: fixed;
  top: 70px;
  right: 32px;
  z-index: 80;
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  flex-wrap: wrap;
  width: max-content;
  max-width: min(460px, calc(100vw - 40px));
  margin: 0;
  padding: 0;
  pointer-events: none;
}
.dashboard-sticky-actions .dashboard-action-btn {
  pointer-events: auto;
  background: color-mix(in srgb, var(--bg-secondary) 88%, transparent);
  box-shadow: var(--shadow);
  backdrop-filter: blur(12px);
}
.dashboard-sticky-actions .dashboard-action-btn-primary {
  background: var(--accent);
  border-color: transparent;
  color: var(--on-accent);
}
.dashboard-action-btn {
  padding: 8px 12px; border-radius: var(--radius-sm);
  border: 1px solid var(--border); background: var(--bg-secondary);
  color: var(--text-primary); font: inherit; font-size: 12px; font-weight: 600;
  cursor: pointer; transition: background 0.15s, border-color 0.15s, transform 0.05s;
}
.dashboard-action-btn:hover { background: var(--bg-hover); border-color: var(--accent); }
.dashboard-action-btn:active { transform: translateY(1px); }
.dashboard-action-btn:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
.dashboard-action-btn-primary {
  background: var(--accent); border-color: transparent; color: var(--on-accent);
}
html:not([data-theme]) .dashboard-action-btn-primary {
  /* White hover text fails against the blue accent during background
     interpolation, so this button snaps directly to the dark hover surface. */
  transition: border-color 0.15s, transform 0.05s;
}
html:not([data-theme]) .dashboard-action-btn-primary:hover {
  background: var(--bg-hover);
  border-color: var(--accent);
  color: #fff;
}

